use xiom.io;
module my_math {
  pub fn fibonacci(n: Int) -> Int
    requires: n >= 0
  {
    if n == 0 { return 0; };
    if n == 1 { return 1; };
    var a = 0;
    var b = 1;
    var i = 2;
    while i <= n {
      let next = a + b;
      a = b;
      b = next;
      i += 1;
    };
    b
  }

  pub fn power(base: Int, exp: Int) -> Int {
    var result = 1;
    var i = 0;
    while i < exp {
      result = result * base;
      i += 1;
    };
    result
  }
}

fn main() -> Int {
  let fib5 = my_math.fibonacci(5);
  let pow2_3 = my_math.power(2, 3);
  io.println(fib5.to_str());
  io.println(pow2_3.to_str());
  return 0;
}
